package id.std.memoryreader;
import android.app.*;import android.os.*;import android.hardware.usb.*;import android.content.*;import android.widget.*;import android.view.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 TextView status; UsbManager manager; LinearLayout rows; Button scan,back; ProgressBar progress; UsbDevice device; UsbInterface iface; UsbDisk disk; FatFiles files; final ArrayDeque<Long> history=new ArrayDeque<>(); long folder=0; boolean busy=false; volatile boolean closed=false; Thread worker;
 final String action="id.std.memoryreader.USB_PERMISSION";
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(action.equals(i.getAction())&&!busy&&device!=null){if(manager.hasPermission(device))open();else status.setText("Izin USB ditolak");}}};
 public void onCreate(Bundle b){super.onCreate(b);manager=(UsbManager)getSystemService(USB_SERVICE);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,new IntentFilter(action),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,new IntentFilter(action));
 LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,64,24,24);l.setBackgroundColor(0xff101c28);
 TextView title=new TextView(this);title.setText("IING STD Memory Reader");title.setTextColor(0xff65e4ce);title.setTextSize(25);l.addView(title);
 status=new TextView(this);status.setTextColor(-1);status.setText("Hubungkan card reader OTG. Mode hanya baca.");l.addView(status);
 scan=new Button(this);scan.setText("Hubungkan & baca memori");l.addView(scan);scan.setOnClickListener(v->connect());
 back=new Button(this);back.setText("Folder sebelumnya");l.addView(back);back.setEnabled(false);back.setOnClickListener(v->{if(!history.isEmpty()){folder=history.pop();browse();}});
 progress=new ProgressBar(this);progress.setVisibility(View.GONE);l.addView(progress);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);l.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(l);}
 void connect(){if(busy)return;device=null;iface=null;int n=0;for(UsbDevice d:manager.getDeviceList().values())for(int i=0;i<d.getInterfaceCount();i++){UsbInterface f=d.getInterface(i);if(f.getInterfaceClass()==8&&f.getInterfaceSubclass()==6&&f.getInterfaceProtocol()==80){device=d;iface=f;n++;}}
 if(n!=1){status.setText(n==0?"Card reader SCSI BOT belum terdeteksi":"Hubungkan satu card reader saja");return;}
 if(manager.hasPermission(device))open();else manager.requestPermission(device,PendingIntent.getBroadcast(this,0,new Intent(action).setPackage(getPackageName()),PendingIntent.FLAG_IMMUTABLE));}
 interface Work{void run()throws Exception;}
 void task(Work work){if(busy||closed)return;busy=true;scan.setEnabled(false);back.setEnabled(false);rows.setEnabled(false);for(int i=0;i<rows.getChildCount();i++)rows.getChildAt(i).setEnabled(false);progress.setVisibility(View.VISIBLE);worker=new Thread(()->{try{work.run();}catch(Exception e){runOnUiThread(()->{if(!closed)status.setText("Gagal: "+e.getMessage());});}finally{if(closed&&disk!=null)disk.close();runOnUiThread(()->{if(closed)return;busy=false;scan.setEnabled(true);back.setEnabled(!history.isEmpty());for(int i=0;i<rows.getChildCount();i++)rows.getChildAt(i).setEnabled(true);progress.setVisibility(View.GONE);});}});worker.start();}
 void open(){rows.removeAllViews();history.clear();folder=0;task(()->{if(disk!=null)disk.close();disk=null;files=null;disk=new UsbDisk(manager,device,iface);files=new FatFiles(FatVolume.discover(disk));load();});}
 void browse(){task(()->load());}
 void load()throws IOException{ArrayList<FatFiles.Entry> list=new ArrayList<>();files.list(folder,e->{if(list.size()>=5000)throw new IOException("Folder terlalu besar");list.add(e);});runOnUiThread(()->{if(closed)return;rows.removeAllViews();status.setText((files.v.fat32?"FAT32":"FAT16")+" | "+list.size()+" item");for(FatFiles.Entry e:list){Button b=new Button(this);b.setAllCaps(false);b.setText((e.directory?"📁 ":"")+e.name+(e.directory?"":" • "+e.size+" B"));rows.addView(b);b.setOnClickListener(v->{if(busy)return;if(e.directory){history.push(folder);folder=e.cluster;browse();}else new AlertDialog.Builder(this).setTitle(e.name).setMessage("Salin ke folder Download di HP?").setPositiveButton("Salin",(d,w)->export(e)).setNegativeButton("Batal",null).show();});}});}
 void export(FatFiles.Entry e){if(Build.VERSION.SDK_INT>=29){task(()->{android.content.ContentValues cv=new android.content.ContentValues();String safe=e.name.replaceAll("[^\\p{L}\\p{N}._ -]","_");if(safe.isEmpty()||safe.equals(".")||safe.equals(".."))safe="recovered";cv.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,safe);cv.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"application/octet-stream");cv.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/IING STD Memory Reader");cv.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);android.net.Uri uri=getContentResolver().insert(android.provider.MediaStore.Downloads.getContentUri(android.provider.MediaStore.VOLUME_EXTERNAL_PRIMARY),cv);if(uri==null)throw new IOException("Destination unavailable");boolean ok=false;try{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Destination unavailable");files.copy(e,out);}cv.clear();cv.put(android.provider.MediaStore.MediaColumns.IS_PENDING,0);if(getContentResolver().update(uri,cv,null,null)!=1)throw new IOException("Cannot publish file");ok=true;}finally{if(!ok)getContentResolver().delete(uri,null,null);}runOnUiThread(()->{if(!closed)status.setText("Tersimpan di Download/IING STD Memory Reader");});});return;}task(()->{File dir=new File(getFilesDir(),"Recovered");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Cannot create destination");String name=e.name.replaceAll("[^\\p{L}\\p{N}._ -]","_");if(name.isEmpty()||name.equals(".")||name.equals(".."))name="recovered";if(name.length()>100)name=name.substring(0,100);File target=File.createTempFile("recovered-","-"+name,dir);boolean ok=false;try{try(OutputStream out=new FileOutputStream(target)){files.copy(e,out);}ok=true;}finally{if(!ok)target.delete();}runOnUiThread(()->{if(!closed)status.setText("Tersalin ke penyimpanan privat aplikasi: "+target.getName());});});}
 protected void onDestroy(){closed=true;unregisterReceiver(receiver);if(busy&&worker!=null)worker.interrupt();else if(disk!=null)disk.close();super.onDestroy();}
}
